head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT10200.gfm';
///////// 1. 변수 및 선언 영역 /////////
scwin.jFilter = ''; //전체, 성공, 실패, 우편함
scwin.allCnt = 0;

//----W-Craft WebSquare 변환 확인: Filter----//

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.getValue() !== "") {
        scwin.listSync(); //alert();

    } else {
        alert("일자를 지정하십시요");
    }
};

scwin.btn_toExcel_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: GridToExcel----//
    MxGrid_1.GridToExcel("지분추출현황", "", "8");
};

//----W-Craft WebSquare 변환 확인: Filter----//
scwin.MxDataSet_OnFilter = function(row) {

    //----W-Craft WebSquare 변환 확인: Filter----//
    if (scwin.jFilter === '') {
        scwin.allCnt++;
        return true;
    } else {

        //----W-Craft WebSquare 변환 확인: Filter----//

        //----W-Craft WebSquare 변환 확인: NameString----//
        if (MxDataSet.NameString(row, "SUC_GUBN") === scwin.jFilter) {
            scwin.allCnt++;
            return true;
        } else {
            return false;
        }
    }
};

scwin.MxComResult_onselchange = function(info) {
    scwin.allCnt = 0;

    //----W-Craft WebSquare 변환 확인: Filter----//
    scwin.jFilter = MxComResult.BindColVal;

    //----W-Craft WebSquare 변환 확인: Filter----//
    if (scwin.jFilter === '전체') scwin.jFilter = '';

    //----W-Craft WebSquare 변환 확인: Filter----//
    MxDataSet.Filter();
    scwin.setCountBox();
};

scwin.MxGrid_1_onlbuttondblclk = function(rowIndex, columnIndex, columnId) {
    if (colid === 'SUC_GUBN' && row <= MxDataSet.countrow && row > 0) {

        //----W-Craft WebSquare 변환 확인: NameValue----//
        if (MxDataSet.NameValue(MxDataSet.RowPosition, "SUC_GUBN") === '실패') scwin.doDelete(MxDataSet.NameValue(MxDataSet.RowPosition, "FORM_CD"), MxDataSet.NameValue(MxDataSet.RowPosition, "ACPT_NO"));
    }
};

///////// 5. 일반/업무 함수 영역 /////////
 //리스트 개수
scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/shrextrc.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.setCountBox = function() {
    textbox_1.setValue("총 " + scwin.allCnt + "건");
};

scwin.doDelete = async function(form_cd, acpt_no) {
    const param = "FORM_CD=" + form_cd + ",ACPT_NO=" + acpt_no;
    alert(acpt_no + ":" + param);
    trDel.KeyName = "toinb_dataid4";

    //----W-Craft WebSquare 변환 확인: Post----//
    // [전환검토] trDel.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    // };
    const sbmOptions = {
        id : "sbm_trDel",
        action : "/shrextrc.do",
        ref : "MxDataSet",
        target : "trDel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

scwin.doDelete1 = async function(form_cd, acpt_no) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    alert(acpt_no);

    //----W-Craft WebSquare 변환 확인: ClearData----//
    mdsDel.ClearData();

    //----W-Craft WebSquare 변환 확인: NameValue----//

    //----W-Craft WebSquare 변환 확인: addRow----//
    mdsDel.addRow(); /*ORG SRC: mdsDel.NameValue(mdsDel.RowPosition, "FORM_CD") = form_cd;*/ X = form_cd; /*ORG SRC: mdsDel.NameValue(mdsDel.RowPosition, "ACPT_NO") = acpt_no;*/ X = acpt_no;
    trDel.KeyName = "toinb_dataid4";

    //----W-Craft WebSquare 변환 확인: Post----//
    const sbmOptions = {
        id : "sbm_trDel",
        action : "/shrextrc.do",
        ref : "mdsDel",
        target : "trDel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_mdsDel",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "mdsDel=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //fn_code1_sync();
    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);

    //----W-Craft WebSquare 변환 확인: Filter----//
    MxDataSet.UseFilter = "true";
};
